shader_type spatial;
render_mode cull_front, unshaded;

uniform vec4 outline_color : source_color = vec4(0.0, 1.0, 1.0, 1.0);
uniform float outline_thickness : hint_range(1.0, 1.5, 0.005) = 1.05;
uniform float emission_energy : hint_range(0.0, 16.0, 0.1) = 3.0;

void vertex() {
	VERTEX *= outline_thickness;
}

void fragment() {
	ALBEDO = outline_color.rgb;
	EMISSION = outline_color.rgb * emission_energy;
}

extends Node3D

@export var cube_scene: PackedScene
@export var cube_container: Node3D
@export var cube_root: Node3D

func _ready():
	for x in range(-1, 2):
		for y in range(-1, 2):
			for z in range(-1, 2):
				if x == 0 and y == 0 and z == 0:
					continue
				var cubie = cube_scene.instantiate()
				cubie.position = Vector3(x, y, z)
				cubie.add_to_group('cubies')
				cube_root.add_child(cubie)

func _unhandled_input(event):
	if is_scrambling:
		return
	if event is InputEventScreenTouch:
		if event.pressed:
			touch_start_pos = event.position
			is_dragging = false
		else:
			if not is_dragging:
				pass
			else:
				is_dragging = false
	elif event is InputEventScreenDrag:
		if not is_dragging:
			if event.position.distance_to(touch_start_pos) > drag_threshold:
				is_dragging = true
		if is_dragging:
			_rotate_cube(event.relative)

func _rotate_cube(drag_motion: Vector2):
	if cube_container == null:
		return
	cube_container.rotate_y(drag_motion.x * sensitivity)
	var new_x = cube_container.rotation.x - (-drag_motion.y * sensitivity)
	cube_container.rotation.x = clamp(new_x, deg_to_rad(-80), deg_to_rad(80))
	velocity_y = -drag_motion.x * sensitivity
	velocity_x = -drag_motion.y * sensitivity

func _process(delta):
	if not is_dragging and (velocity_y != 0.0 or velocity_x != 0.0):
		cube_container.rotate_y(velocity_y)
		var new_x = cube_container.rotation.x + velocity_x
		cube_container.rotation.x = clamp(new_x, deg_to_rad(-80), deg_to_rad(80))
		velocity_y = lerp(velocity_y, 0.0, 10.0 * delta)
		velocity_x = lerp(velocity_x, 0.0, 10.0 * delta)
		if abs(velocity_y) < 0.001:
			velocity_y = 0.0
		if abs(velocity_x) < 0.001:
			velocity_x = 0.0

# Добавьте это после функции: _process
func _handle_tap(tap_pos: Vector2):
	if is_rotating:
		return
	var from = camera.project_ray_origin(tap_pos)
	var to = from + camera.project_ray_normal(tap_pos) * 100.0
	var space_state = get_world_3d().direct_space_state
	var query = PhysicsRayQueryParameters3D.create(from, to)
	var result = space_state.intersect_ray(query)
	if result:
		if result.collider.is_in_group('cubies'):
			rotate_face_by_normal(result.normal, 0.2)

func rotate_face_by_normal(global_normal: Vector3, duration: float = 0.25):
	if is_rotating:
		return
	is_rotating = true
	var local_normal = cube_root.global_transform.basis.inverse() * global_normal
	local_normal = local_normal.round()
	var axis = Vector3.ZERO
	if abs(local_normal.x) > 0.5:
		axis = Vector3.RIGHT
	elif abs(local_normal.y) > 0.5:
		axis = Vector3.UP
	elif abs(local_normal.z) > 0.5:
		axis = Vector3.BACK
	var cubies_to_rotate = []
	for child in cube_root.get_children():
		if child.is_in_group('cubies'):
			if abs(child.position.round().dot(local_normal) - 1.0) < 0.1:
				cubies_to_rotate.append(child)
	if cubies_to_rotate.is_empty():
		is_rotating = false
		return
	var pivot = Node3D.new()
	cube_root.add_child(pivot)
	for c in cubies_to_rotate:
		c.reparent(pivot)
	var angle = deg_to_rad(90) * local_normal.dot(axis)
	var target_rotation = pivot.rotation + axis * angle
	if duration <= 0.0:
		pivot.rotation = target_rotation
		_finish_rotation(cubies_to_rotate, pivot)
		is_rotating = false
	else:
		var tween = create_tween()
		tween.set_trans(Tween.TRANS_QUAD).set_ease(Tween.EASE_IN_OUT)
		tween.tween_property(pivot, 'rotation', target_rotation, duration)
		await tween.finished
		_finish_rotation(cubies_to_rotate, pivot)
		is_rotating = false

func _finish_rotation(cubies: Array, pivot: Node3D):
	for c in cubies:
		c.reparent(cube_root)
		c.position = c.position.round()
		c.rotation = c.rotation.snapped(Vector3(deg_to_rad(90), deg_to_rad(90), deg_to_rad(90)))
	pivot.queue_free()
	is_timer_running = true

# Добавьте это после var is_scrambling: bool = false
var local_faces = [
	Vector3(1,0,0), Vector3(-1,0,0), 
	Vector3(0,1,0), Vector3(0,-1,0), 
	Vector3(0,0,1), Vector3(0,0,-1)
]

# Добавьте это после _finish_rotation
func _on_scramble_button_pressed():
	if is_scrambling:
		return
	is_scrambling = true
	while is_rotating:
		await get_tree().process_frame
	for i in range(20):
		var random_local_face = local_faces.pick_random()
		var global_normal = cube_root.global_transform.basis * random_local_face
		await rotate_face_by_normal(global_normal, 0.08)
		await get_tree().create_timer(0.02).timeout
	is_scrambling = false
